import React, { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { pause, play } from '../audio/player';

declare const require: (moduleName: string) => unknown;

export interface AudioMessage {
  id: string;
  audioId?: string;
  localUri?: string;
  uri?: string;
  durationMs?: number;
}

interface MediaClient {
  mediaUrl(audioId: string): string;
}

export interface AudioBubbleProps {
  message: AudioMessage;
  isOwn?: boolean;
  client?: MediaClient;
}

function formatDuration(durationMs: number): string {
  const seconds = Math.max(0, Math.round(durationMs / 1000));
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

function getDefaultClient(): MediaClient | null {
  try {
    const module = require('../api/client') as {
      client?: MediaClient;
      default?: MediaClient;
      mediaUrl?: MediaClient['mediaUrl'];
    };
    if (module.client) return module.client;
    if (module.default) return module.default;
    if (module.mediaUrl) return { mediaUrl: module.mediaUrl };
  } catch {
    return null;
  }
  return null;
}

function waveformFor(id: string): number[] {
  let seed = 0;
  for (let index = 0; index < id.length; index += 1) {
    seed = (seed * 31 + id.charCodeAt(index)) >>> 0;
  }
  return Array.from({ length: 20 }, (_, index) => {
    seed = (Math.imul(seed ^ index, 1103515245) + 12345) >>> 0;
    return 7 + (seed % 18);
  });
}

export function AudioBubble({ message, isOwn = false, client }: AudioBubbleProps): React.JSX.Element {
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [hasError, setHasError] = useState(false);
  const waveform = useMemo(() => waveformFor(message.id), [message.id]);
  const source = message.localUri ?? message.uri ??
    (message.audioId ? (client ?? getDefaultClient())?.mediaUrl(message.audioId) : undefined);

  const togglePlayback = async (): Promise<void> => {
    setHasError(false);
    if (isPlaying) {
      await pause();
      setIsPlaying(false);
      return;
    }
    if (!source) {
      setHasError(true);
      return;
    }
    try {
      setIsPlaying(true);
      await play(source, {
        onProgress: (value) => setProgress(value),
        onEnd: () => {
          setIsPlaying(false);
          setProgress(0);
        },
      });
    } catch {
      setIsPlaying(false);
      setProgress(0);
      setHasError(true);
    }
  };

  const activeColor = isOwn ? '#2481cc' : '#3390ec';
  const inactiveColor = isOwn ? '#8fc4e8' : '#a8c9df';

  return (
    <View style={[styles.container, isOwn ? styles.outgoing : styles.incoming]}>
      <Pressable
        accessibilityLabel={isPlaying ? 'Приостановить аудиосообщение' : 'Воспроизвести аудиосообщение'}
        accessibilityRole='button'
        onPress={() => void togglePlayback()}
        style={[styles.playButton, { backgroundColor: activeColor }]}
      >
        <Text style={styles.playIcon}>{isPlaying ? 'Ⅱ' : '▶'}</Text>
      </Pressable>
      <View style={styles.content}>
        <View accessibilityLabel={`Прогресс ${Math.round(progress * 100)}%`} style={styles.waveform}>
          {waveform.map((height, index) => (
            <View
              key={`${message.id}-${index}`}
              style={[
                styles.waveBar,
                {
                  backgroundColor: index / waveform.length <= progress ? activeColor : inactiveColor,
                  height,
                },
              ]}
            />
          ))}
        </View>
        <Text style={[styles.duration, isOwn && styles.outgoingText]}>
          {hasError ? 'ошибка' : formatDuration(message.durationMs ?? 0)}
        </Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    borderRadius: 18,
    flexDirection: 'row',
    minWidth: 210,
    paddingHorizontal: 10,
    paddingVertical: 8,
  },
  incoming: { backgroundColor: '#ffffff' },
  outgoing: { backgroundColor: '#e7ffdb' },
  playButton: {
    alignItems: 'center',
    borderRadius: 20,
    height: 40,
    justifyContent: 'center',
    width: 40,
  },
  playIcon: { color: '#ffffff', fontSize: 17, fontWeight: '700' },
  content: { flex: 1, marginLeft: 9 },
  waveform: { alignItems: 'center', flexDirection: 'row', height: 26 },
  waveBar: { borderRadius: 2, marginRight: 2, width: 3 },
  duration: { color: '#70808b', fontSize: 11, marginTop: 2 },
  outgoingText: { color: '#5e8d54' },
});

export default AudioBubble;
EOF"}
